import{A as e,K as t,P as n,c as r,d as i,h as a,m as o,p as s}from"./vendor~app~SearchBox~404.html~30_信号与图像~20_信号与图像~13_光流与运动分~pe382js8-DW9Brykq.js";import{t as c}from"./app-B6GYz4Ts.js";var l=JSON.parse(`{"path":"/DeepLearning/EpochalAlgorithms/04_InstanceSegmentation.html","title":"实例分割算法：为每个目标生成独立 Mask | 跨时代算法","lang":"zh-CN","frontmatter":{"title":"实例分割算法：为每个目标生成独立 Mask","date":"2026/07/05","categories":["跨时代算法"],"tags":["跨时代算法","实例分割","图像分割"]},"readingTime":{"minutes":18.05,"words":5415},"git":{"createdTime":1783837248000,"updatedTime":1792752019000,"contributors":[{"name":"jinkai","username":"jinkai","email":"1213860588@qq.com","commits":2,"avatar":"https://avatars.githubusercontent.com/jinkai?v=4","url":"https://github.com/jinkai"},{"name":"jk","username":"jk","email":"jk@yaogan","commits":1,"avatar":"https://avatars.githubusercontent.com/jk?v=4","url":"https://github.com/jk"}]},"filePathRelative":"DeepLearning/EpochalAlgorithms/04_InstanceSegmentation.md","headers":[]}`),u={name:`04_InstanceSegmentation.md`};function d(c,l,u,d,f,p){let m=n(`VPLink`);return e(),i(`div`,null,[l[24]||=r(`h2`,{id:`_1-实例分割任务是什么`,tabindex:`-1`},[r(`a`,{class:`header-anchor`,href:`#_1-实例分割任务是什么`},[r(`span`,null,`1. 实例分割任务是什么？`)])],-1),l[25]||=r(`p`,null,`前面已经讲过两个相关任务：`,-1),r(`ul`,null,[r(`li`,null,[a(m,{href:`./02_SemanticSegmentation.md`},{default:t(()=>[...l[0]||=[o(`语义分割`,-1)]]),_:1}),l[1]||=o(`：判断每个像素是什么类别。`,-1)]),r(`li`,null,[a(m,{href:`./03_ObjectDetection.md`},{default:t(()=>[...l[2]||=[o(`目标检测`,-1)]]),_:1}),l[3]||=o(`：找出每个目标的类别和边界框。`,-1)])]),l[26]||=s(`<p>实例分割把这两个要求放到了一起：</p><blockquote><p><strong>既要区分同一类别里的不同目标，又要找出每个目标包含哪些像素。</strong></p></blockquote><p>比如一张图里有两辆车，语义分割会把两辆车的像素都标成“车”；目标检测会分别给出两个边界框；实例分割则要生成两个独立的 Mask，分别表示车 1 和车 2 的准确轮廓。</p><h3 id="_1-1-从目标框到独立-mask" tabindex="-1"><a class="header-anchor" href="#_1-1-从目标框到独立-mask"><span>1.1 从目标框到独立 Mask</span></a></h3><p>三种任务的输出可以这样对照：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>语义分割：每个像素一个类别，同类目标不分彼此</span></span>
<span class="line"><span>目标检测：每个目标一个矩形框，不描述框内的准确轮廓</span></span>
<span class="line"><span>实例分割：每个目标一个独立 Mask，直接描述目标包含哪些像素</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="/aosai-blog/DeepLearning/EpochalAlgorithms/04_instance_segmentation_task.png" alt="Fig.1 语义分割、目标检测与实例分割的输出区别" tabindex="0" loading="lazy"><figcaption>Fig.1 语义分割、目标检测与实例分割的输出区别</figcaption></figure><p>矩形框里通常还会包含背景。实例 Mask 则由像素组成：属于当前目标的像素记为 1，不属于当前目标的像素记为 0。</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>车 1 Mask：只标出第一辆车的像素</span></span>
<span class="line"><span>车 2 Mask：只标出第二辆车的像素</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>因此，实例分割不只是“框得更紧”，而是把每个目标从背景和其他实例中逐像素分离出来。</p><h3 id="_1-2-一个实例分割结果包含什么" tabindex="-1"><a class="header-anchor" href="#_1-2-一个实例分割结果包含什么"><span>1.2 一个实例分割结果包含什么？</span></a></h3><p>一个实例分割结果通常包含三部分：</p><ul><li><strong>类别（Class）</strong>：这个实例是什么。</li><li><strong>实例 Mask（Instance Mask）</strong>：这个实例包含哪些像素。</li><li><strong>置信度（Confidence Score）</strong>：模型对这个结果有多确定。</li></ul><p>很多模型还会同时输出边界框，但边界框不是实例分割最终必须提供的结果。只要有实例 Mask，就可以找到 Mask 覆盖范围的最小外接矩形，反过来得到边界框。</p><p>所以实例分割算法可以定义成：</p><blockquote><p><strong>学习一个函数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>f</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">f(x)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span>，把一张图像 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi></mrow><annotation encoding="application/x-tex">x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> 映射成一组实例，每个实例包含类别、独立 Mask 和置信度。</strong></p></blockquote><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>f</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><mo stretchy="false">{</mo><mo stretchy="false">(</mo><msub><mi>m</mi><mi>i</mi></msub><mo separator="true">,</mo><msub><mi>c</mi><mi>i</mi></msub><mo separator="true">,</mo><msub><mi>s</mi><mi>i</mi></msub><mo stretchy="false">)</mo><msubsup><mo stretchy="false">}</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>N</mi></msubsup></mrow><annotation encoding="application/x-tex">f(x)=\\{(m_i,c_i,s_i)\\}_{i=1}^{N} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1413em;vertical-align:-0.25em;"></span><span class="mopen">{(</span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose"><span class="mclose">}</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span></span></p><ul><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span>：预测出的实例数量。</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>m</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">m_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>：第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个实例的 Mask。</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>c</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">c_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>：第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个实例的类别。</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">s_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>：第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个实例的置信度。</li></ul><p>图里有几个目标，最终就应该输出几个实例；如果图里没有目标，结果可以是空集合。任务目标也可以概括成一句话：<strong>类别要正确，Mask 要准确，同时尽量不漏掉、不误报、不重复输出实例。</strong></p><h3 id="_1-3-实例分割的稳定算法骨架" tabindex="-1"><a class="header-anchor" href="#_1-3-实例分割的稳定算法骨架"><span>1.3 实例分割的稳定算法骨架</span></a></h3><p>不同实例分割模型的结构差别很大，但它们一直在完成同一套任务：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>输入图像</span></span>
<span class="line"><span>→ 提取图像特征</span></span>
<span class="line"><span>→ 产生一组实例预测</span></span>
<span class="line"><span>→ 建立预测与真实实例的对应关系</span></span>
<span class="line"><span>→ 优化实例类别和 Mask</span></span>
<span class="line"><span>→ 输出最终实例集合</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里最关键的变化，是监督单位从“像素类别”变成了“独立实例”。语义分割只需要知道第 <code>(i, j)</code> 个像素是什么类别；实例分割还要知道它属于哪一个目标。</p><h3 id="_1-4-怎样训练、预测和评价" tabindex="-1"><a class="header-anchor" href="#_1-4-怎样训练、预测和评价"><span>1.4 怎样训练、预测和评价？</span></a></h3><p>一张训练图像通常带有两部分标注：</p><ul><li><code>masks</code>：形状为 <code>(N, H, W)</code>，记录 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个真实实例各自的 Mask。</li><li><code>labels</code>：形状为 <code>(N,)</code>，记录每个实例的真实类别。</li></ul><p>如果模型依赖目标检测，还会使用 <code>boxes</code> 监督边界框。训练时，模型先产生一组实例预测，再确定每个预测应该学习哪一个真实实例。核心损失可以概括成：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><msub><mi>L</mi><mrow><mi>c</mi><mi>l</mi><mi>s</mi></mrow></msub><mo>+</mo><msub><mi>λ</mi><mrow><mi>m</mi><mi>a</mi><mi>s</mi><mi>k</mi></mrow></msub><msub><mi>L</mi><mrow><mi>m</mi><mi>a</mi><mi>s</mi><mi>k</mi></mrow></msub><mo>+</mo><msub><mi>λ</mi><mrow><mi>b</mi><mi>o</mi><mi>x</mi></mrow></msub><msub><mi>L</mi><mrow><mi>b</mi><mi>o</mi><mi>x</mi></mrow></msub></mrow><annotation encoding="application/x-tex">L=L_{cls}+\\lambda_{mask}L_{mask}+\\lambda_{box}L_{box} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><ul><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>L</mi><mrow><mi>c</mi><mi>l</mi><mi>s</mi></mrow></msub></mrow><annotation encoding="application/x-tex">L_{cls}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>：分类损失，让实例类别正确。</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>L</mi><mrow><mi>m</mi><mi>a</mi><mi>s</mi><mi>k</mi></mrow></msub></mrow><annotation encoding="application/x-tex">L_{mask}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>：Mask 损失，让预测区域接近真实区域。</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>L</mi><mrow><mi>b</mi><mi>o</mi><mi>x</mi></mrow></msub></mrow><annotation encoding="application/x-tex">L_{box}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">b</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>：边界框损失，只在模型预测边界框时使用。</li></ul>`,29),r(`p`,null,[l[6]||=o(`Mask 损失常由像素级二元交叉熵、`,-1),a(m,{href:`../LossFunction/04_FocalLoss.md`},{default:t(()=>[...l[4]||=[o(`Focal Loss`,-1)]]),_:1}),l[7]||=o(` 或 `,-1),a(m,{href:`../LossFunction/03_DiceLoss.md`},{default:t(()=>[...l[5]||=[o(`Dice Loss`,-1)]]),_:1}),l[8]||=o(` 组成。计算完损失后，模型通过反向传播更新参数，再进入下一批、下一个 epoch。`,-1)]),l[27]||=s(`<figure><img src="/aosai-blog/DeepLearning/EpochalAlgorithms/04_instance_segmentation_pipeline.png" alt="Fig.2 实例分割的训练闭环与预测输出" tabindex="0" loading="lazy"><figcaption>Fig.2 实例分割的训练闭环与预测输出</figcaption></figure><p>预测时不再提供真实 Mask，模型只根据图像输出一组实例结果。传统模型还要筛掉低置信度和重复预测；一对一集合预测模型则可以直接输出实例集合。</p><p>评价时，需要先比较预测 Mask 和真实 Mask 的重叠程度：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Mask\xA0IoU</mtext><mo>=</mo><mfrac><mtext>预测\xA0Mask\xA0与真实\xA0Mask\xA0的交集像素数</mtext><mtext>预测\xA0Mask\xA0与真实\xA0Mask\xA0的并集像素数</mtext></mfrac></mrow><annotation encoding="application/x-tex">\\text{Mask IoU}=\\frac{\\text{预测 Mask 与真实 Mask 的交集像素数}} {\\text{预测 Mask 与真实 Mask 的并集像素数}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">Mask\xA0IoU</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0574em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">预测</span><span class="mord">\xA0Mask\xA0</span><span class="mord cjk_fallback">与真实</span><span class="mord">\xA0Mask\xA0</span><span class="mord cjk_fallback">的并集像素数</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">预测</span><span class="mord">\xA0Mask\xA0</span><span class="mord cjk_fallback">与真实</span><span class="mord">\xA0Mask\xA0</span><span class="mord cjk_fallback">的交集像素数</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p>`,4),r(`p`,null,[l[10]||=o(`在此基础上，再计算 `,-1),l[11]||=r(`strong`,null,`Mask AP`,-1),l[12]||=o(`。它和`,-1),a(m,{href:`../EvaluationMetrics/11_AP.md`},{default:t(()=>[...l[9]||=[o(`目标检测中的 AP`,-1)]]),_:1}),l[13]||=o(`使用同一套置信度排序、匹配与面积计算逻辑，区别是：目标检测使用边界框 IoU 判断是否匹配，实例分割使用 Mask IoU。`,-1)]),l[28]||=s(`<h2 id="_2-实例分割必须解决哪些设计问题" tabindex="-1"><a class="header-anchor" href="#_2-实例分割必须解决哪些设计问题"><span>2. 实例分割必须解决哪些设计问题？</span></a></h2><p>实例分割的任务定义长期稳定，但“怎样得到每一个独立 Mask”没有唯一答案。不同模型的主要差别，可以还原成下面三个设计问题。</p><h3 id="_2-1-怎样区分同一类别的不同实例" tabindex="-1"><a class="header-anchor" href="#_2-1-怎样区分同一类别的不同实例"><span>2.1 怎样区分同一类别的不同实例？</span></a></h3><p>假设图里有两辆相互靠近的车。模型不仅要知道这些像素属于“车”，还要把它们拆成车 1 和车 2。常见方法可以分成三类：</p><ul><li><strong>检测后分割（Detect-then-segment）</strong>：先用边界框区分目标，再在每个目标区域内生成 Mask。</li><li><strong>位置驱动（Location-based）</strong>：根据目标中心或空间位置，让不同位置分别负责不同实例。</li><li><strong>实例查询（Instance Query）</strong>：准备一组可学习的 Query，让每个 Query 尝试寻找并分割一个实例。</li><li><strong>提示驱动（Prompt-based）</strong>：由点、框、图像示例或文字指出要寻找的目标，再生成对应实例的 Mask。</li></ul><p>它们都在解决同一个问题：图像最终要输出数量不固定的一组实例，模型必须给每个实例安排一个独立的预测位置。</p><h3 id="_2-2-每个实例的-mask-怎样生成" tabindex="-1"><a class="header-anchor" href="#_2-2-每个实例的-mask-怎样生成"><span>2.2 每个实例的 Mask 怎样生成？</span></a></h3><p>区分实例之后，还要决定怎样表示它的准确轮廓。</p><p><strong>候选区域内逐像素预测</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>目标边界框 → 取出区域特征 → 在区域内部预测二值 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这类方法先缩小范围，再判断框内哪些像素属于当前实例。Mask R-CNN 就采用这种方式。</p><p><strong>原型 Mask 与实例系数组合</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>整张图生成一组原型 Mask</span></span>
<span class="line"><span>+ 每个实例预测一组组合系数</span></span>
<span class="line"><span>→ 组合成当前实例的 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原型 Mask 可以重复使用，模型不必为每个实例单独运行一套完整的 Mask 网络，因此更适合实时预测。YOLACT 和部分实时实例分割模型采用这种思路。</p><p><strong>Query 直接预测 Mask</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>一个 Query → 一个类别 + 一个完整 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>每个 Query 读取图像特征，再直接产生自己的类别和 Mask。Mask2Former 属于这类集合式 mask prediction。</p><p><strong>提示条件下生成 Mask</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>图像特征 + 点 / 框 / 示例 / 文字提示 → 提示对应的一个或多个 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>提示告诉模型“现在要分什么”。SAM 1 和 SAM 2 主要根据视觉提示选择特定目标，SAM 3 还可以根据文字或图像示例找出同一概念的全部实例。</p><h3 id="_2-3-预测怎样匹配真实实例并避免重复" tabindex="-1"><a class="header-anchor" href="#_2-3-预测怎样匹配真实实例并避免重复"><span>2.3 预测怎样匹配真实实例并避免重复？</span></a></h3><p>一张图可能只有 5 个真实实例，模型却会产生几十甚至几百个候选预测。训练时必须确定每个预测应该学习哪一个真实实例。</p>`,22),r(`p`,null,[l[15]||=o(`传统的检测后分割和密集预测方法通常使用`,-1),l[16]||=r(`strong`,null,`一对多匹配（One-to-many Matching）`,-1),l[17]||=o(`：一个真实实例可以让多个候选预测同时学习。这样能提供更多训练信号，但预测时也可能对同一个实例输出多个结果，因此通常需要`,-1),a(m,{href:`./03_ObjectDetection.md#_4-1-nms-%E4%B8%BA%E4%BB%80%E4%B9%88%E8%83%BD%E5%A4%9F%E5%88%A0%E9%99%A4%E9%87%8D%E5%A4%8D%E6%A1%86`},{default:t(()=>[...l[14]||=[o(`非极大值抑制（Non-Maximum Suppression，NMS）`,-1)]]),_:1}),l[18]||=o(`去重。`,-1)]),r(`p`,null,[l[20]||=o(`Query-based 方法通常使用`,-1),l[21]||=r(`strong`,null,`一对一匹配（One-to-one Matching）`,-1),l[22]||=o(`：一个真实实例只分配给一个 Query，其他 Query 学习“无目标”。`,-1),a(m,{href:`./03_ObjectDetection.md#_4-2-object-query-%E4%B8%8E%E5%8C%88%E7%89%99%E5%88%A9%E5%8C%B9%E9%85%8D`},{default:t(()=>[...l[19]||=[o(`匈牙利匹配`,-1)]]),_:1}),l[23]||=o(`会综合类别和 Mask 的匹配代价，为整组预测寻找总代价较小的一对一组合。`,-1)]),l[29]||=s(`<p>提示分割在预测时由提示限定目标范围，不一定需要先把所有候选预测分配给固定类别。自动生成大量 Mask 时，仍然需要根据 Mask 质量、稳定性和重叠程度筛掉低质量或重复结果。</p><p>所以实例分割也不只是“给目标检测增加一张 Mask”。当实例来源、Mask 表示和匹配方式发生变化时，整套实例生成方法也会随之变化。</p><h2 id="_3-实例分割算法的演进" tabindex="-1"><a class="header-anchor" href="#_3-实例分割算法的演进"><span>3. 实例分割算法的演进</span></a></h2><p>理解了上面三个设计问题，再看论文演进就会更清楚：每条路线都在重新回答“实例从哪里来、Mask 怎样生成、重复结果怎样处理”。</p><h3 id="_3-1-2017-检测后分割-mask-r-cnn-成为经典基线" tabindex="-1"><a class="header-anchor" href="#_3-1-2017-检测后分割-mask-r-cnn-成为经典基线"><span>3.1 2017：检测后分割，Mask R-CNN 成为经典基线</span></a></h3><p><a href="https://arxiv.org/abs/1703.06870" target="_blank" rel="noopener noreferrer">Mask R-CNN</a> 建立在 Faster R-CNN 之上。Faster R-CNN 原本已经能够产生候选区域，并预测每个区域的类别和边界框；Mask R-CNN 在旁边增加了一条 Mask 分支：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>候选区域特征</span></span>
<span class="line"><span>├── 类别分支：这个目标是什么？</span></span>
<span class="line"><span>├── 边界框分支：目标框应该怎样修正？</span></span>
<span class="line"><span>└── Mask 分支：框内哪些像素属于这个目标？</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三个分支共享图像特征，但分别完成分类、定位和像素分割。因为候选区域已经把不同目标分开，Mask 分支只需要在当前区域内区分“属于这个实例”和“不属于这个实例”。</p><p>Mask R-CNN 还使用了<a href="#_4-1-roialign-%E4%B8%BA%E4%BB%80%E4%B9%88%E5%AF%B9-mask-%E8%BE%B9%E7%95%8C%E9%87%8D%E8%A6%81">感兴趣区域对齐（Region of Interest Align，RoIAlign）</a>，减少候选区域在提取特征时产生的位置偏移。实例 Mask 对像素位置很敏感，这个改动对边界质量很重要。</p><p>这条路线可以概括成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>先检测实例 → 再为每个实例生成 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>它把目标检测和像素分割组合成了一套清晰、稳定的框架，后来也长期作为实例分割的重要基线。</p><h3 id="_3-2-2019-2020-直接生成-mask-并走向实时" tabindex="-1"><a class="header-anchor" href="#_3-2-2019-2020-直接生成-mask-并走向实时"><span>3.2 2019-2020：直接生成 Mask，并走向实时</span></a></h3><p>Mask R-CNN 需要为每个候选区域提取特征并运行 Mask 分支。目标数量增加时，这些逐实例计算也会增加。于是一些模型开始寻找更直接、更适合实时预测的办法。</p><p><a href="https://arxiv.org/abs/1904.02689" target="_blank" rel="noopener noreferrer">YOLACT（You Only Look At CoefficienTs）</a> 把 Mask 生成拆成两个并行任务：</p><ol><li>整张图只生成一次原型 Mask。</li><li>每个实例预测一组组合系数。</li></ol><p>最后用不同系数组合相同的原型，就能得到不同实例的 Mask。详细组合过程放在<a href="#_4-2-%E5%8E%9F%E5%9E%8B-mask-%E4%B8%8E%E5%AE%9E%E4%BE%8B%E7%B3%BB%E6%95%B0%E6%80%8E%E6%A0%B7%E7%BB%84%E5%90%88">原型 Mask 与实例系数</a>中。</p><p><a href="https://arxiv.org/abs/1912.04488" target="_blank" rel="noopener noreferrer">按位置分割目标（Segmenting Objects by Locations，SOLO）</a> 则进一步摆脱边界框。它把图像划分成网格，根据目标中心位置决定由哪个位置负责当前实例，再直接输出这个实例的类别和 Mask：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>目标中心位置 → 确定负责位置 → 直接预测实例 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>两者的具体设计不同，但共同说明了一件事：<strong>实例分割不一定要先得到候选框，再逐个运行 Mask 分支。</strong></p><ul><li>YOLACT：用共享原型和实例系数减少重复计算。</li><li>SOLO：根据位置区分实例，直接生成 Mask。</li></ul><p>这一阶段让单阶段、实时和无框实例分割成为了清晰的研究路线。</p><h3 id="_3-3-2021-2022-query-直接预测一组-mask" tabindex="-1"><a class="header-anchor" href="#_3-3-2021-2022-query-直接预测一组-mask"><span>3.3 2021-2022：Query 直接预测一组 Mask</span></a></h3><p><a href="https://arxiv.org/abs/2107.06278" target="_blank" rel="noopener noreferrer">MaskFormer</a> 提出 <strong>Mask 分类（Mask Classification）</strong>：模型不再把分割只理解成“每个像素独立分类”，而是预测一组 Mask，并给每个 Mask 分配一个类别。</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>一组 Query</span></span>
<span class="line"><span>→ 每个 Query 输出一个类别和一个 Mask</span></span>
<span class="line"><span>→ 匈牙利匹配真实区域</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://arxiv.org/abs/2112.01527" target="_blank" rel="noopener noreferrer">Mask2Former</a> 继续强化这套结构，让同一个框架可以完成语义分割、实例分割和全景分割。做实例分割时，每个有效 Query 对应一个独立实例；没有找到目标的 Query 输出“无目标”。</p><p>这条路线和 DETR 目标检测非常接近：</p><ul><li>DETR：一个 Object Query 输出一个类别和边界框。</li><li>Mask2Former：一个 Mask Query 输出一个类别和 Mask。</li></ul><p>训练时使用一对一匹配，预测结果天然是一组实例，因此不需要先放置 Anchor，也不必依赖传统的一对多候选框流程。</p><h3 id="_3-4-2023-2025-从提示分割到开放词汇实例分割" tabindex="-1"><a class="header-anchor" href="#_3-4-2023-2025-从提示分割到开放词汇实例分割"><span>3.4 2023-2025：从提示分割到开放词汇实例分割</span></a></h3><p>Mask2Former 仍然在一组预先规定的类别里预测实例。2023 年，<a href="https://ai.meta.com/research/publications/segment-anything/" target="_blank" rel="noopener noreferrer">分割一切模型（Segment Anything Model，SAM）</a> 改变了 Mask 的使用方式：模型不再只接受图像，还会接收点、边界框或已有 Mask 等<strong>视觉提示（Visual Prompt）</strong>。</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>图像 + 点 / 框 / Mask 提示 → SAM → 提示所指目标的 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>SAM 1 本身不负责回答目标是什么类别，也不一定一次找出某个类别的全部实例。它更像一个通用 Mask 生成器：用户或其他模型先指出“要分哪里”，SAM 再生成准确轮廓。它也可以在整张图上密集采样提示，自动产生大量不带类别的候选 Mask。</p><p>2024 年，<a href="https://ai.meta.com/research/sam2/" target="_blank" rel="noopener noreferrer">分割一切模型 2（Segment Anything Model 2，SAM 2）</a> 把这套能力从静态图像扩展到图像和视频。用户只需要在某一帧中用点、框或 Mask 选中目标，模型就能利用记忆模块把这个目标的 Mask 传播到后续帧：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>一帧中的目标提示 → 生成 Mask → 记住目标 → 在视频中持续分割和跟踪</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>2025 年，<a href="https://github.com/facebookresearch/sam3" target="_blank" rel="noopener noreferrer">分割一切模型 3（Segment Anything Model 3，SAM 3）</a> 又补上了关键的一步：除了点和框，还可以用文字或图像示例描述一个<strong>概念（Concept）</strong>，模型会找出、分割并跟踪符合这个概念的全部实例。</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>图像 / 视频 + “红色汽车”</span></span>
<span class="line"><span>→ 找出所有符合描述的汽车</span></span>
<span class="line"><span>→ 为每辆车生成独立 Mask</span></span>
<span class="line"><span>→ 在视频中保持实例身份</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这叫做<strong>可提示概念分割（Promptable Concept Segmentation，PCS）</strong>。它和传统实例分割的区别在于类别从哪里来：</p><ul><li>传统实例分割：类别集合在训练前固定，例如 COCO 的 80 类。</li><li>SAM 3：概念由预测时的文字或图像示例给出，可以分割训练类别表之外的目标。</li></ul><p>所以 SAM 不是简单替换了 Mask R-CNN 的一个分支。它把实例分割从“训练一个固定类别模型”，扩展成了“用提示调用一个分割基础模型”。这类模型已经广泛用于交互式分割、数据自动标注、开放词汇分割和视频目标跟踪。</p><h3 id="_3-5-现在-经典、实时、统一与基础模型并存" tabindex="-1"><a class="header-anchor" href="#_3-5-现在-经典、实时、统一与基础模型并存"><span>3.5 现在：经典、实时、统一与基础模型并存</span></a></h3><p>Query-based 方法出现后，检测后分割和实时单阶段方法并没有消失。实际研究和工程中，几条路线仍在同时使用：</p><ul><li><strong>Mask R-CNN 路线</strong>：结构清楚，检测与 Mask 分支容易理解和修改，仍是常见基线。</li><li><strong>实时实例分割路线</strong>：强调速度和部署，<a href="https://docs.ultralytics.com/tasks/segment/" target="_blank" rel="noopener noreferrer">Ultralytics YOLO Segmentation</a> 会直接输出每个实例的 Mask、类别、置信度和边界框。</li><li><strong>Query-based 路线</strong>：强调端到端集合预测，以及语义、实例和全景分割的统一。</li><li><strong>SAM 基础模型路线</strong>：强调零样本迁移、视觉或文字提示、自动标注，以及图像和视频中的通用 Mask 生成。</li></ul><p>这里还要区分 YOLO26 和 SAM 3。<a href="https://docs.ultralytics.com/models/sam-3" target="_blank" rel="noopener noreferrer">Ultralytics 已经集成 SAM 3</a>，也支持 YOLO26 实例分割，但它们仍是两个独立模型：</p><ul><li><code>yolo26n-seg.pt</code>：固定类别、速度快，适合实时部署。</li><li><code>sam3.pt</code>：根据文字、示例、点或框分割，适合开放词汇和交互式任务。</li></ul><p>工程中还可以让 YOLO 先检测目标，再把边界框交给 SAM 生成 Mask，常用于<a href="https://docs.ultralytics.com/models/sam/#auto-annotation" target="_blank" rel="noopener noreferrer">自动标注</a>。这是一条组合流水线，不代表 YOLO26 的网络结构内部使用了 SAM 3。</p><p>这些路线不是互相替代，而是对类别范围、速度、交互方式、视频能力和部署成本做出的不同选择。</p><h3 id="_3-6-抽象总结-变的是怎样得到每个实例的-mask" tabindex="-1"><a class="header-anchor" href="#_3-6-抽象总结-变的是怎样得到每个实例的-mask"><span>3.6 抽象总结：变的是怎样得到每个实例的 Mask</span></a></h3><table><thead><tr><th>演进路线</th><th>实例从哪里来</th><th>Mask 怎样生成</th><th>类别或提示来源</th><th>代表模型</th></tr></thead><tbody><tr><td>检测后分割</td><td>候选区域</td><td>区域内逐像素预测</td><td>固定类别标签</td><td>Mask R-CNN</td></tr><tr><td>单阶段直接生成</td><td>密集位置或目标中心</td><td>原型组合或位置对应的 Mask</td><td>固定类别标签</td><td>YOLACT、SOLO</td></tr><tr><td>Query 集合预测</td><td>一组可学习 Query</td><td>每个 Query 直接预测 Mask</td><td>固定类别标签</td><td>MaskFormer、Mask2Former</td></tr><tr><td>提示式基础模型</td><td>点、框、示例或文字</td><td>提示条件下生成实例 Mask</td><td>视觉提示或开放词汇</td><td>SAM、SAM 2、SAM 3</td></tr></tbody></table><p>这些模型改变的是实例来源、Mask 表示、匹配方式，以及类别从哪里来。传统实例分割的算法抽象仍然是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>输入一张图像</span></span>
<span class="line"><span>→ 输出数量不固定的一组实例</span></span>
<span class="line"><span>→ 每个实例包含类别、独立 Mask 和置信度</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>SAM 路线在输入端增加了提示：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>输入图像 / 视频 + 提示</span></span>
<span class="line"><span>→ 输出提示对应的一组独立 Mask</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>两条路线共同稳定的部分没有变：<strong>最终都要把不同实例分开，并为每个实例生成独立 Mask。</strong></p><h2 id="_4-总结和扩展" tabindex="-1"><a class="header-anchor" href="#_4-总结和扩展"><span>4. 总结和扩展</span></a></h2><h3 id="_4-1-roialign-为什么对-mask-边界重要" tabindex="-1"><a class="header-anchor" href="#_4-1-roialign-为什么对-mask-边界重要"><span>4.1 RoIAlign 为什么对 Mask 边界重要？</span></a></h3><p>Faster R-CNN 中的候选区域坐标不一定正好落在特征图的整数格点上。早期的 RoI Pooling 会把这些小数坐标取整，再把候选区域切成固定大小的网格。</p><p>对于目标检测来说，一点取整误差可能还能接受；但实例分割要判断每个像素属于目标还是背景，特征和原图错开一点，Mask 边界也会跟着偏移。</p><p><strong>感兴趣区域对齐（Region of Interest Align，RoIAlign）</strong> 不再直接取整坐标，而是使用双线性插值计算采样位置的特征值：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-text"><span class="line"><span>RoI Pooling：小数坐标 → 取整 → 提取特征</span></span>
<span class="line"><span>RoIAlign：    保留小数坐标 → 插值采样 → 提取特征</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>它没有改变实例分割的任务定义，只是让候选区域特征与原图位置对齐得更准确，从而改善 Mask 的空间边界。</p><h3 id="_4-2-原型-mask-与实例系数怎样组合" tabindex="-1"><a class="header-anchor" href="#_4-2-原型-mask-与实例系数怎样组合"><span>4.2 原型 Mask 与实例系数怎样组合？</span></a></h3><p>YOLACT 不会为每个实例单独生成一张完整 Mask，而是先为整张图生成 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi></mrow><annotation encoding="application/x-tex">K</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 张原型 Mask：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>P</mi><mn>1</mn></msub><mo separator="true">,</mo><msub><mi>P</mi><mn>2</mn></msub><mo separator="true">,</mo><mo>…</mo><mo separator="true">,</mo><msub><mi>P</mi><mi>K</mi></msub></mrow><annotation encoding="application/x-tex">P_1,P_2,\\ldots,P_K </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>每个实例再预测 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi></mrow><annotation encoding="application/x-tex">K</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 个组合系数：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>c</mi><mrow><mi>i</mi><mn>1</mn></mrow></msub><mo separator="true">,</mo><msub><mi>c</mi><mrow><mi>i</mi><mn>2</mn></mrow></msub><mo separator="true">,</mo><mo>…</mo><mo separator="true">,</mo><msub><mi>c</mi><mrow><mi>i</mi><mi>K</mi></mrow></msub></mrow><annotation encoding="application/x-tex">c_{i1},c_{i2},\\ldots,c_{iK} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mord mtight">2</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个实例的 Mask 由这些原型加权组合得到：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>M</mi><mi>i</mi></msub><mo>=</mo><mi>σ</mi><mrow><mo fence="true">(</mo><munderover><mo>∑</mo><mrow><mi>k</mi><mo>=</mo><mn>1</mn></mrow><mi>K</mi></munderover><msub><mi>c</mi><mrow><mi>i</mi><mi>k</mi></mrow></msub><msub><mi>P</mi><mi>k</mi></msub><mo fence="true">)</mo></mrow></mrow><annotation encoding="application/x-tex">M_i=\\sigma\\left(\\sum_{k=1}^{K}c_{ik}P_k\\right) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.1304em;vertical-align:-1.3021em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size4">(</span></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">ik</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size4">)</span></span></span></span></span></span></span></p><p>可以把原型理解成模型为当前图像准备的一组基础形状和空间成分。不同实例使用不同系数，同样一组原型就能组合出不同 Mask。</p><p>这样做的关键不是“原型长得像某一种固定物体”，而是把大量计算放到整张图共享的原型分支里，每个实例只需要额外预测一组较短的系数。</p><h3 id="_4-3-和语义分割、全景分割、提示分割的关系" tabindex="-1"><a class="header-anchor" href="#_4-3-和语义分割、全景分割、提示分割的关系"><span>4.3 和语义分割、全景分割、提示分割的关系</span></a></h3><ul><li><strong>语义分割</strong>：每个像素有类别，但不区分同类实例。</li><li><strong>实例分割</strong>：区分每个可数目标，并为每个目标生成独立 Mask。</li><li><strong>全景分割</strong>：既处理道路、天空这类背景区域，也区分车、人这类独立实例。</li><li><strong>提示分割</strong>：根据点、框、示例或文字提示输出区域，类别和实例范围由提示方式决定。</li></ul><p>SAM 1 和 SAM 2 主要根据点、框或 Mask 找到特定目标，不一定自动给出类别；SAM 3 可以根据文字或示例找出某个概念的全部实例，已经和开放词汇实例分割发生明显重合。但它们仍然不等于固定类别、固定输出流程的传统有监督实例分割。</p><h3 id="_4-4-工程生态-detectron2、mmdetection-与-ultralytics" tabindex="-1"><a class="header-anchor" href="#_4-4-工程生态-detectron2、mmdetection-与-ultralytics"><span>4.4 工程生态：Detectron2、MMDetection 与 Ultralytics</span></a></h3><p>实例分割已经形成了成熟的工程生态：</p><ul><li><a href="https://github.com/facebookresearch/detectron2" target="_blank" rel="noopener noreferrer">Detectron2</a> 提供 Mask R-CNN 等经典实现，适合研究区域检测和实例分割框架。</li><li><a href="https://github.com/open-mmlab/mmdetection" target="_blank" rel="noopener noreferrer">MMDetection</a> 集成 Mask R-CNN、YOLACT、SOLO、Mask2Former 等不同路线，适合通过配置比较模型。</li><li><a href="https://docs.ultralytics.com/tasks/segment/" target="_blank" rel="noopener noreferrer">Ultralytics</a> 同时提供 YOLO 实例分割与 SAM 1/2/3 接口，也能组合检测器和 SAM 自动生成数据标注。</li></ul><p>这些工具箱不是新的实例分割算法。它们把模型、数据集、训练配置和部署接口组织到统一工程框架中，让使用者不必从零实现完整流程。</p>`,77)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};